use std::fs

fn prec(op: string) -> int {
    if op == "^" { return 3 }
    if op == "*" || op == "/" { return 2 }
    if op == "+" || op == "-" { return 1 }
    0
}

fn convert(line: string) -> string {
    let mut out: Vec<string> = []
    let mut stack: Vec<string> = []
    let mut expect = true
    let mut num = ""
    let mut toks: Vec<string> = []
    for c in line.chars() {
        let d = c >= '0' && c <= '9'
        if d {
            num = num + c.to_string()
        } else {
            if num != "" {
                toks.push(num)
                num = ""
            }
            if c != ' ' && c != '\t' && c != '\r' {
                toks.push(c.to_string())
            }
        }
    }
    if num != "" {
        toks.push(num)
    }
    for t in toks {
        let first = t.chars().next().unwrap_or(' ')
        if first >= '0' && first <= '9' {
            if !expect { return "error" }
            out.push(t)
            expect = false
        } else if t == "(" {
            if !expect { return "error" }
            stack.push(t)
        } else if t == ")" {
            if expect { return "error" }
            let mut found = false
            while stack.len() > 0 {
                let top = stack.pop().unwrap_or("")
                if top == "(" {
                    found = true
                    break
                }
                out.push(top)
            }
            if !found { return "error" }
        } else if prec(t) > 0 {
            if expect { return "error" }
            while stack.len() > 0 {
                let top = stack[stack.len() - 1]
                let pt = prec(top)
                if pt == 0 { break }
                let p = prec(t)
                if pt > p || (pt == p && t != "^") {
                    out.push(stack.pop().unwrap_or(""))
                } else {
                    break
                }
            }
            stack.push(t)
            expect = true
        } else {
            return "error"
        }
    }
    if expect { return "error" }
    while stack.len() > 0 {
        let top = stack.pop().unwrap_or("")
        if top == "(" { return "error" }
        out.push(top)
    }
    out.join(" ")
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" { continue }
        println(convert(line))
    }
}

